import{_ as r,A as o,o as n,c as d,j as t,a,C as i,X as c}from"./chunks/framework.CNGPadWr.js";const f=JSON.parse('{"title":"Memory and performance","titleTemplate":":title · CellPack Rust","description":"","frontmatter":{},"headers":[],"relativePath":"rust/docs/performance.md","filePath":"performance.md"}'),l={name:"rust/docs/performance.md"};function p(h,e,m,u,g,k){const s=o("DocDiagram");return n(),d("div",null,[e[0]||(e[0]=t("h1",{id:"memory-and-performance",tabindex:"-1"},[a("Memory and performance "),t("a",{class:"header-anchor",href:"#memory-and-performance","aria-label":'Permalink to "Memory and performance"'},"​")],-1)),e[1]||(e[1]=t("p",null,"Tune a representative workload only after checking decoded values, output order, and ownership. Cache hit counts, modeled time, and small examples describe different parts of a run; none alone establishes end-to-end training throughput.",-1)),e[2]||(e[2]=t("h2",{id:"memory-reservations",tabindex:"-1"},[a("Memory reservations "),t("a",{class:"header-anchor",href:"#memory-reservations","aria-label":'Permalink to "Memory reservations"'},"​")],-1)),e[3]||(e[3]=t("p",null,[t("code",null,"Loader::memory_estimate(cache_bytes, slots, world)"),a(" estimates a default page-only configuration; zero bytes selects no planning. Use "),t("code",null,"memory_estimate_for(&planning, slots, world)"),a(" for an actual fixed or online plan, including row caching and zero-budget plans.")],-1)),i(s,{name:"memory-budgets"}),e[4]||(e[4]=c(`<table tabindex="0"><thead><tr><th><code>MemoryEstimate</code> field</th><th>Reservation</th></tr></thead><tbody><tr><td><code>cache_frame_bytes</code></td><td>Planned page and row frames</td></tr><tr><td><code>generation_bytes</code></td><td>A generation word per cache frame</td></tr><tr><td><code>private_frame_bytes</code></td><td>Worker-private miss buffers</td></tr><tr><td><code>worker_scratch_bytes</code></td><td>Decode, conversion, mapping, and process scratch</td></tr><tr><td><code>plan_ring_bytes</code></td><td>Published plan entries and their variable-length data</td></tr><tr><td><code>metadata_bytes</code></td><td>Chunk metadata, decode tables, column and panel maps</td></tr><tr><td><code>output_ring_bytes</code></td><td>Output data and ring control</td></tr><tr><td><code>known_reservation_bytes</code></td><td>Sum of the known reservations</td></tr></tbody></table><p>These values are not measured RSS and are not a total process-memory limit. Allocator overhead, compiler state, and the OS page cache are outside the estimate. Reserved virtual memory need not all be resident.</p><p>Private buffers depend on worker count, in-flight depth, schema count, record-page sizes, and a reserve for oversized records. Row-cache and plan-ring sizing must also account for wide decoded rows, rather than only compressed page counts. The planner&#39;s horizon retains additional state, which grows with the number of accesses it covers.</p><p>Use <code>RingLayout::bytes()</code>, <code>control_bytes()</code>, and <code>data_bytes()</code> for actual aligned ring sizes. A rough payload expression, <code>slots × slot_cells × sum(cell_bytes)</code>, excludes padding and control metadata.</p><h2 id="execution-settings" tabindex="-1">Execution settings <a class="header-anchor" href="#execution-settings" aria-label="Permalink to &quot;Execution settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th><code>LoaderConfig</code> field</th><th>Default</th><th>Tuning role</th></tr></thead><tbody><tr><td><code>workers</code></td><td>16</td><td>Parallel reads, decoding, mapping, and callbacks</td></tr><tr><td><code>backend</code></td><td><code>Uring</code></td><td>Asynchronous io_uring or blocking <code>Pread</code></td></tr><tr><td><code>max_inflight_per_worker</code></td><td>64</td><td>Outstanding positions per worker</td></tr><tr><td><code>claim_batch</code></td><td>8</td><td>Accesses per claim, rounded and bounded to positions and slots</td></tr><tr><td><code>slot_cells</code></td><td>256</td><td>Positions in one output slot</td></tr><tr><td><code>window</code></td><td>Derived</td><td>Maximum execution lead in slots</td></tr><tr><td><code>profile</code></td><td><code>None</code></td><td>Optional timing mask</td></tr><tr><td><code>cpus</code></td><td>Empty</td><td>Optional worker CPU affinity</td></tr></tbody></table><p>Start with uncached execution and a validated data source. Increase workers and in-flight depth while observing CPU, I/O, memory reservations, and stalls. Blocking <code>Pread</code> does not issue asynchronous reads merely because in-flight depth is large. More ring slots help absorb consumer variation, but cannot remove a persistent consumer bottleneck.</p><p>Add page caching next, then evaluate decoded rows with measured costs. Keep input files, exact accesses, schema semantics, batch size, CPU placement, and timing boundaries fixed when comparing modes.</p><h2 id="runtime-kernels" tabindex="-1">Runtime kernels <a class="header-anchor" href="#runtime-kernels" aria-label="Permalink to &quot;Runtime kernels&quot;">​</a></h2><p>The runtime probes CPU support and binds a kernel set once per process. On x86-64 it selects the best supported scalar, AVX2, or AVX-512 implementation. Other architectures use scalar codec kernels; this does not imply that the entire Linux loader supports every platform.</p><p><code>CELLPACK_KERNELS=scalar|avx2|avx512</code> caps the selected ISA. A cap does not force unsupported instructions. Invalid values fail initialization. Set it before the first kernel use; changing it after initialization cannot rebind existing contexts.</p><p>For example, a scalar equivalence run from the repository root:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CELLPACK_KERNELS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">scalar</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --manifest-path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/cellpack/examples/Cargo.toml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --bin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quickstart</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tmp/cellpack-guide/scalar</span></span></code></pre></div><h2 id="interpret-i-o-carefully" tabindex="-1">Interpret I/O carefully <a class="header-anchor" href="#interpret-i-o-carefully" aria-label="Permalink to &quot;Interpret I/O carefully&quot;">​</a></h2><p><code>IoStats</code> counts application requests and returned bytes. With buffered I/O, those reads can be served by the OS page cache. Direct I/O can make device traffic easier to interpret but still needs filesystem and storage verification. Do not label application bytes as physical device bytes.</p><p>Report cache state, direct-I/O setting, backend, CPU placement, input shape and dtype, access distribution, schemas, consumer work, and elapsed-time scope with any throughput result. See <a href="/cellpack-docs/rust/docs/profiling.html">profiling</a> to find the limiting stage.</p>`,16))])}const y=r(l,[["render",p]]);export{f as __pageData,y as default};
